cat > tests/list-order.test.ts <<'EOF'
import assert from "node:assert/strict";
import { DatabaseSync } from "node:sqlite";
import { runInNewContext } from "node:vm";
import { after, before, describe, it } from "node:test";
import { newDbPath, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
  created_at: string;
  completed_at: string | null;
}

async function createTask(server: Running, title: string): Promise<void> {
  const response = await fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ title }),
  });
  assert.equal(response.status, 201);
}

async function listTitles(server: Running): Promise<string[]> {
  const response = await fetch(`${server.baseUrl}/api/tasks`);
  assert.equal(response.status, 200);
  const { tasks } = (await response.json()) as { tasks: Task[] };
  return tasks.map((task) => task.title);
}

/** Writes rows straight into the SQLite file, so a test controls created_at exactly. */
function insertRows(dbPath: string, rows: { title: string; createdAt: string }[]): void {
  const db = new DatabaseSync(dbPath);
  try {
    db.exec("BEGIN");
    const insert = db.prepare(
      "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?)",
    );
    for (const { title, createdAt } of rows) insert.run(title, createdAt, createdAt);
    db.exec("COMMIT");
  } finally {
    db.close();
  }
}

describe("SL-008 list open tasks newest first, with an empty state", () => {
  describe("AC-1: tasks added in the order A, B, C", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: GET /api/tasks lists C, B, A", async () => {
      for (const title of ["A", "B", "C"]) {
        await createTask(server, title);
        await new Promise((resolve) => setTimeout(resolve, 5));
      }
      assert.deepEqual(await listTitles(server), ["C", "B", "A"]);
    });

    it("AC-1: ordering follows created_at, not the order of the ids", async () => {
      const dbPath = newDbPath();
      const own = await startServer(dbPath);
      try {
        insertRows(dbPath, [
          { title: "middle", createdAt: "2026-01-02T00:00:00.000Z" },
          { title: "newest", createdAt: "2026-01-03T00:00:00.000Z" },
          { title: "oldest", createdAt: "2026-01-01T00:00:00.000Z" },
        ]);
        assert.deepEqual(await listTitles(own), ["newest", "middle", "oldest"]);
      } finally {
        await own.stop();
      }
    });
  });

  describe("AC-2: tasks created at the same instant", () => {
    it("AC-2: the one saved last is listed first, every time", async () => {
      const dbPath = newDbPath();
      const server = await startServer(dbPath);
      try {
        const instant = "2026-01-01T12:00:00.000Z";
        insertRows(dbPath, [
          { title: "first", createdAt: instant },
          { title: "second", createdAt: instant },
          { title: "third", createdAt: instant },
        ]);
        for (let attempt = 0; attempt < 5; attempt++) {
          assert.deepEqual(await listTitles(server), ["third", "second", "first"]);
        }
      } finally {
        await server.stop();
      }
    });
  });

  describe("AC-3: an empty list", () => {
    let server: Running;
    let html: string;
    let script: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
      script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-3: the page has an empty-state element with a message", () => {
      assert.match(html, /<[a-z]+[^>]+id=["']empty-state["'][^>]*>\s*\S[^<]*</);
    });

    /** Runs public/app.js against a minimal fake page that serves the given tasks. */
    async function runPage(tasks: { title: string }[]) {
      const element = (): Record<string, any> => ({
        hidden: false,
        textContent: "",
        children: [] as unknown[],
        value: "",
        addEventListener() {},
        replaceChildren(...nodes: unknown[]) {
          this.children = nodes;
        },
      });
      const elements: Record<string, Record<string, any>> = {
        "task-form": element(),
        "task-title": element(),
        "task-list": element(),
        "empty-state": element(),
      };
      const sandbox = {
        document: {
          getElementById: (id: string) => elements[id],
          createElement: () => element(),
        },
        fetch: async () => ({ json: async () => ({ tasks }) }),
      };
      runInNewContext(script, sandbox);
      await new Promise((resolve) => setImmediate(resolve));
      return elements;
    }

    it("AC-3: with no tasks the empty state is shown and the list is empty", async () => {
      const page = await runPage([]);
      assert.equal(page["empty-state"].hidden, false);
      assert.equal(page["task-list"].children.length, 0);
    });

    it("AC-3: with tasks the empty state is hidden", async () => {
      const page = await runPage([{ title: "A" }]);
      assert.equal(page["empty-state"].hidden, true);
      assert.equal(page["task-list"].children.length, 1);
    });

    it("AC-3: GET /api/tasks answers 200 with an empty list", async () => {
      const response = await fetch(`${server.baseUrl}/api/tasks`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { tasks: [] });
    });
  });

  describe("AC-4: about 1000 stored tasks", () => {
    it("AC-4: p95 of 20 sequential GET /api/tasks is under 100 ms and the body under 400000 bytes", async () => {
      const dbPath = newDbPath();
      const server = await startServer(dbPath);
      try {
        const base = Date.parse("2026-01-01T00:00:00.000Z");
        insertRows(
          dbPath,
          Array.from({ length: 1000 }, (_, i) => ({
            title: `Task number ${i} ${"x".repeat(100)}`,
            createdAt: new Date(base + i * 1000).toISOString(),
          })),
        );

        const durations: number[] = [];
        let bytes = 0;
        for (let i = 0; i < 20; i++) {
          const start = performance.now();
          const response = await fetch(`${server.baseUrl}/api/tasks`);
          const body = await response.arrayBuffer();
          durations.push(performance.now() - start);
          assert.equal(response.status, 200);
          bytes = body.byteLength;
        }
        durations.sort((a, b) => a - b);
        const p95 = durations[Math.ceil(0.95 * durations.length) - 1];
        assert.ok(p95 < 100, `p95 was ${p95.toFixed(1)} ms`);
        assert.ok(bytes < 400000, `body was ${bytes} bytes`);
      } finally {
        await server.stop();
      }
    });
  });
});
